import os, re, sys, subprocess
used = set(subprocess.run(['bash','-c',"grep -rhoE 'R\\.string\\.[a-z0-9_]+' " + sys.argv[1] + "/../java | sed 's/R.string.//'"], capture_output=True, text=True).stdout.split())
for k in list(S):
    if k not in used: del S[k]

root = sys.argv[1]
def esc(s):
    s = s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    s = s.replace("'", "\\'").replace('"', '\\"').replace("’", "\\'").replace("\n", "\\n")
    return s
for idx, folder in enumerate(["values", "values-or", "values-hi"]):
    out = ['<?xml version="1.0" encoding="utf-8"?>']
    if idx: out.append("<!-- Machine-drafted translation. Must be reviewed by a native speaker before release (PRD 9.4). -->")
    out.append("<resources>")
    for k, v in S.items():
        t = v[idx]
        attrs = ""
        if k in ("lang_or", "lang_hi", "lang_en", "map_attribution", "sos_button") and idx == 0:
            attrs = ' translatable="false"' if k != "sos_button" else ""
        if "%" in t and not re.search(r"%\d\$", t):
            attrs += ' formatted="false"'
        if idx and k in ("lang_or", "lang_hi", "lang_en", "map_attribution"):
            continue
        out.append(f'    <string name="{k}"{attrs}>{esc(t)}</string>')
    out.append("</resources>\n")
    os.makedirs(f"{root}/{folder}", exist_ok=True)
    open(f"{root}/{folder}/strings.xml", "w", encoding="utf-8").write("\n".join(out))
print(len(S))
